<?php require_once __DIR__.'/config/config.php';require_login();$id=(int)($_GET['id']??0);$s=$conn->prepare('SELECT p.*,u.username,u.display_name,u.avatar_url FROM posts p JOIN users u ON u.id=p.user_id WHERE p.id=?');$s->bind_param('i',$id);$s->execute();$post=$s->get_result()->fetch_assoc();if(!$post){http_response_code(404);exit('Post not found.');}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'comment';$uid=current_user_id();if($action==='report'){$reason=trim($_POST['reason']??'');if($reason!==''){$s=$conn->prepare('INSERT INTO reports(post_id,reporter_id,reason) VALUES(?,?,?)');$s->bind_param('iis',$id,$uid,$reason);$s->execute();flash('Report sent to the moderators.');}}else{$body=trim($_POST['body']??'');if($body===''||mb_strlen($body)>1000)flash('Comment must be 1–1,000 characters.','error');else{$s=$conn->prepare('INSERT INTO comments(post_id,user_id,body) VALUES(?,?,?)');$s->bind_param('iis',$id,$uid,$body);$s->execute();notify_user($conn,(int)$post['user_id'],$uid,'comment',$id);flash('Comment added!');}}redirect('post.php?id='.$id);}$s=$conn->prepare('SELECT c.*,u.username,u.display_name,u.avatar_url FROM comments c JOIN users u ON u.id=c.user_id WHERE c.post_id=? ORDER BY c.created_at ASC');$s->bind_param('i',$id);$s->execute();$comments=$s->get_result();$page_title='Post discussion';require __DIR__.'/includes/header.php';?>
<?php require __DIR__.'/includes/post_card.php';?><div class="card composer"><h2>Leave a comment</h2><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><textarea name="body" maxlength="1000" required placeholder="Write a kind comment..."></textarea><div class="form-actions"><small class="muted">Keep it respectful.</small><button class="btn">Comment ♡</button></div></form></div><h2 class="section-title">Comments</h2><?php if(!$comments->num_rows):?><div class="empty-state">No comments yet.</div><?php endif;?><?php while($c=$comments->fetch_assoc()):?><div class="card comment"><div class="post-author"><a class="avatar" href="profile.php?u=<?=e(rawurlencode($c['username']))?>"><?=avatar_html($c['avatar_url'],$c['display_name'])?></a><div><a class="author-name" href="profile.php?u=<?=e(rawurlencode($c['username']))?>"><?=e($c['display_name'])?></a><small>@<?=e($c['username'])?> · <?=e($c['created_at'])?></small></div></div><p><?=nl2br(e($c['body']))?></p></div><?php endwhile;?><details class="report-box"><summary>Report this post</summary><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="report"><textarea name="reason" maxlength="500" required placeholder="Tell moderators why you are reporting this post"></textarea><button class="btn btn-light">Send report</button></form></details><?php require __DIR__.'/includes/footer.php';?>